+  const filePath = path.resolve(outputDir, `.${relativePath}`);
+  const relative = path.relative(outputDir, filePath);
+  if (relative.startsWith(`..${path.sep}`) || relative === '..' || path.isAbsolute(relative)) {
+    send(response, 403, 'Forbidden');
+    return;
+  }
