6: interface CliOptions {
7:   contentDir?: string;
8:   outputDir?: string;
9:   templatesDir?: string;
10:   port?: number;
11: }
12: 
13: function usage(): string {
14:   return 'Usage: ssg <build|serve> [--content <dir>] [--output <dir>] [--templates <dir>] [--port <number>]';
15: }
16: 
17: function parseOptions(args: string[], allowPort: boolean): CliOptions {
18:   const options: CliOptions = {};
19:   for (let index = 0; index < args.length; index += 1) {
20:     const option = args[index];
21:     if (option !== '--content' && option !== '--output' && option !== '--templates' && (option !== '--port' || !allowPort)) {
22:       throw new Error(`Unknown option: ${option}`);
23:     }
